-- Import the existing website catalog into Supabase.
-- Idempotent: re-running updates matching slugs instead of creating duplicates.
-- Source: src/data/streetwearData.ts on branch admin-panel.
begin;

insert into public.brands
  (name,slug,city,founded_year,description,logo_text,logo_url,website,telegram,aesthetic,status)
values
('HRDCR','hrdcr','Санкт-Петербург',2018,'Культовый петербургский хардкор-бренд. Суровая нордическая эстетика, плотный тяжелый хлопок, сырые необработанные швы и аутентичный дух андеграундной сцены.','HRDCR',null,'https://hrdcr.ru','https://t.me/hrdcr_spb','Хардкор / Нордик Гранж','published'),
('ACOLYTE','acolyte','Москва',2020,'Постапокалиптический киберпанк и футуристичный теквир. Анатомический крой, технологичные мембранные ткани, магнитная фурнитура Fidlock и модульные карманы.','ACOLYTE',null,'https://acolyte.tech','https://t.me/acolyte_lab','Киберпанк / Теквир','published'),
('MOLOTOV','molotov','Пермь',2015,'Уральский уличный бренд с крепким сибирским характером. Утилитарный крой, надежные ткани повышенной плотности и честное независимое производство.','MOLOTOV',null,'https://molotov.ru','https://t.me/molotov_streetwear','Утилитарный / Херитейдж','published'),
('YALTA 94','yalta-94','Ялта',2021,'Ностальгический постсоветский прибрежный рейв. Тяжелый вываренный хлопок, кислотные варки, архивные шрифты и кастомная ручная шелкография.','YALTA 94',null,'https://yalta94.com','https://t.me/yalta94_club','Рейв 90-х / Винтаж','published'),
('die young','die-young','Екатеринбург',2019,'Мрачный уральский романтизм, деконструкция и DIY-подход. Лимитированные тиражи, сложные графические коллажи и бескомпромиссный оверсайз.','die young',null,'https://dieyoung.store','https://t.me/dieyoung_ekb','Мрачный романтизм / DIY','published'),
('ВОЛЧОК','volchok','Москва',2014,'Первопроходцы новой волны российского стритвира. Мрачные смыслы, фольклорные аллюзии, готическая графика и узнаваемый манифест поколения.','ВОЛЧОК',null,'https://volchok.ru','https://t.me/volchokclothing','Русская готика / Новая Волна','published')
on conflict (slug) do update set
  name=excluded.name, city=excluded.city, founded_year=excluded.founded_year,
  description=excluded.description, logo_text=excluded.logo_text, logo_url=excluded.logo_url,
  website=excluded.website, telegram=excluded.telegram, aesthetic=excluded.aesthetic,
  status='published', updated_at=now();

insert into public.products
  (slug,name,brand_id,category,category_label,price,sizes,description,composition,
   care_instructions,delivery_info,image_url,gallery,external_shop_url,is_new,featured,color,sku,status)
values
('hrdcr-untamed-tee','Футболка Oversize «Untamed Heavyweight»',(select id from public.brands where slug='hrdcr'),'t-shirts','Футболки',4900,array[]::text[],'Тяжелая оверсайз футболка из плотного хлопка пенье плотностью 280 г/м². Вываренная винтажная текстура Dark Graphite, заниженная линия плеча и шелкографический принт с авторской типографикой. Не садится и держит плотный монументальный силуэт.','100% гребенной хлопок пенье (280 г/м²)','Стирка при 30°C на деликатном режиме наизнанку. Не сушить в барабане. Гладить с изнаночной стороны.','Доставка СДЭК до двери или пункта выдачи по всей России (2-4 дня). Самовывоз в Санкт-Петербурге. Бесплатный возврат 14 дней.','./images/oversize_tee.jpg',array['./images/oversize_tee.jpg','./images/hero_editorial.jpg','https://hrdcr.ru/products/untamed-tee','Washed Graphite','HRD-24-TEE-01']::text[],null,false,false,null,null,'published'),
('acolyte-studio-hoodie','Худи Boxy Fit «Studio Silence»',(select id from public.brands where slug='acolyte'),'hoodies','Худи и свитшоты',9800,array[]::text[],'Премиальное худи из сверхплотного 3-х ниточного футера с начесом плотностью 460 г/м². Глубокий двойной капюшон с анатомической посадкой, скрытый карман-кенгуру со скрытыми молниями YKK, матовая минималистичная микропечать на груди.','85% хлопок, 15% полиэстер для сохранения геометрии капюшона (460 г/м²)','Бережная машинная стирка при температуре до 30°C. Избегать отжима выше 600 об/мин.','Курьерская доставка по Москве в день заказа или СДЭК Экспресс по России и СНГ.','./images/hoodie_black.jpg',array['./images/hoodie_black.jpg','./images/hero_editorial.jpg','https://acolyte.tech/shop/studio-silence-hoodie','Pitch Black','ACL-24-HD-04']::text[],null,false,false,null,null,'published'),
('acolyte-tactical-cargo','Карго Брюки «Tactical Modular V2»',(select id from public.brands where slug='acolyte'),'pants','Брюки и карго',13500,array[]::text[],'Технические брюки-карго из армированного рипстопа с DWR-пропиткой. 8 функциональных карманов, стропы регулировки объема на липучках Velcro, усиленные колени с вытачками для свободы движения и фирменные D-кольца для карабинов.','65% хлопок, 35% износостойкий нейлон Cordura с влагоотталкивающим покрытием','Ручная или деликатная стирка при 30°C. Не использовать кондиционер, чтобы не повредить DWR мембрану.','Отправка в течение 24 часов. Доставка по РФ курьером с возможностью примерки.','./images/cargo_pants.jpg',array['./images/cargo_pants.jpg','./images/hero_editorial.jpg','https://acolyte.tech/shop/tactical-modular-v2','Matte Black','ACL-24-CRG-02']::text[],null,false,false,null,null,'published'),
('molotov-permafrost-zip','Зип-Худи Heavy «Permafrost Edition»',(select id from public.brands where slug='molotov'),'hoodies','Худи и свитшоты',8900,array[]::text[],'Флагманское уральское зип-худи. Тракторная металлическая молния с гравированным бегунком, плотный петлевой футер без начеса 430 г/м², широкий оверсайз крой с упругими манжетами в рубчик. Выдерживает жесткие сибирские ветра.','100% органический хлопок (430 г/м²)','Стирать застегнутым наизнанку при 30°C. Гладить паром.','Экспресс СДЭК из Перми (2-3 дня до Москвы и Петербурга).','./images/hoodie_black.jpg',array['./images/hoodie_black.jpg','https://molotov.ru/products/permafrost-zip','Deep Raven Black','MLT-24-ZIP-09']::text[],null,false,false,null,null,'published'),
('yalta94-priboy-tee','Футболка Boxy «Прибой 94 Acid Wash»',(select id from public.brands where slug='yalta-94'),'t-shirts','Футболки',4500,array[]::text[],'Культовая модель бренда с ручной кислотной варкой Acid Mineral Wash. Каждый экземпляр имеет уникальный мраморный рисунок. Архивный графический принт в технике водной шелкографии, приятный к телу и неубиваемый.','100% плотный вываренный хлопок (260 г/м²)','Стирать при 30°C жидким средством для темных вещей.','Доставка по РФ от 3 до 5 дней. Фирменный упаковочный зип-пакет с постером в подарок.','./images/oversize_tee.jpg',array['./images/oversize_tee.jpg','https://yalta94.com/catalog/priboy-acid-tee','Acid Mineral Gray','YLT-24-PRB-01']::text[],null,false,false,null,null,'published'),
('dieyoung-mgla-hoodie','Худи Oversize «Мгла / Деконструкция»',(select id from public.brands where slug='die-young'),'hoodies','Худи и свитшоты',10400,array[]::text[],'Деконструированное худи с открытыми срезами швов, двойными манжетами и вышитой монограммой бренда на капюшоне. Плотная турецкая хлопковая ткань 480 г/м², обеспечивающая массивный силуэт.','100% тяжелый хлопок без синтетических примесей','Сухая чистка или бережная ручная стирка в холодной воде.','Лимитированный тираж 150 единиц. Номерной сертификат в комплекте.','./images/hoodie_black.jpg',array['./images/hoodie_black.jpg','https://dieyoung.store/item/mgla-deconstructed','Faded Black','DY-24-MGL-03']::text[],null,false,false,null,null,'published'),
('volchok-oskolki-long','Лонгслив Oversize «Осколки Новой Волны»',(select id from public.brands where slug='volchok'),'t-shirts','Футболки',5200,array[]::text[],'Удлиненный лонгслив со спущенным рукавом и объемным кроем. Готическая кириллическая графика на рукавах и спине, плотная горловина из кашкорсе, сохраняющая форму после сотен стирок.','100% компакт-пенье хлопок (240 г/м²)','Стирка при 30°C вывернутым наизнанку.','Доставка по РФ и СНГ. Флагманский магазин в Москве на Хлебозаводе.','./images/oversize_tee.jpg',array['./images/oversize_tee.jpg','https://volchok.ru/catalog/longsleeve-oskolki','Carbon Black','VLC-24-LNG-07']::text[],null,false,false,null,null,'published'),
('hrdcr-wide-pants','Широкие Брюки «Baggy Heavy Drill»',(select id from public.brands where slug='hrdcr'),'pants','Брюки и карго',11200,array[]::text[],'Ультра-широкие брюки из жесткого хлопкового твила плотностью 380 г/м². Глубокие складки у пояса, внутренний утягивающий шнур, скрытые карманы с усилением хольнитенами и идеальная драпировка на кроссовки.','100% хлопковый саржевый твил','Машинная стирка при 40°C. Гладить при средней температуре.','Отправка СДЭК с трек-номером в день оформления.','./images/cargo_pants.jpg',array['./images/cargo_pants.jpg','https://hrdcr.ru/products/baggy-drill-pants','Washed Ash Black','HRD-24-PNT-05']::text[],null,false,false,null,null,'published'),
('acolyte-chest-rig','Нагрудная Сумка «Tactical Rig 01»',(select id from public.brands where slug='acolyte'),'accessories','Аксессуары',6400,array[]::text[],'Нагрудная модульная сумка-жилет из влагозащитной Cordura 1000D. Четырехточечная подвесная система с быстросбросами, лазерная резка MOLLE-панелей, прорезиненные молнии Aquaguard и внутренний карабин для ключей.','100% нейлон Cordura 1000D, полиамидные стропы, фурнитура YKK','Чистить влажной губкой. Не стирать в стиральной машине.','Доставка по всей РФ 2-4 дня в фирменном чехле.','./images/cargo_pants.jpg',array['./images/cargo_pants.jpg','https://acolyte.tech/shop/tactical-rig-01','Tactical Black','ACL-24-ACC-01']::text[],null,false,false,null,null,'published'),
('molotov-balaclava-wool','Вязаная Балаклава «Nordic Shield»',(select id from public.brands where slug='molotov'),'accessories','Аксессуары',3200,array[]::text[],'Теплая анатомическая балаклава из смесовой мериносовой шерсти крупного фактурного рубчика. Мягкая внутренняя флисовая подкладка для защиты дыхания от ветра, эластичный вырез для глаз, жаккардовый патч с логотипом.','50% шерсть мериноса, 50% акрил Soft-Touch','Ручная стирка в прохладной воде со специальным средством для шерсти.','В наличии на складе. Отправка на следующий рабочий день.','./images/hoodie_black.jpg',array['./images/hoodie_black.jpg','https://molotov.ru/catalog/balaclava-nordic','Charcoal Black','MLT-24-ACC-03']::text[],null,false,false,null,null,'published'),
('dieyoung-raw-denim','Джинсы Wide Leg «Raw Concrete»',(select id from public.brands where slug='die-young'),'pants','Брюки и карго',12900,array[]::text[],'Широкие джинсы из плотного необработанного японского денима плотностью 14.5 oz. Фактурный селвидж-край, фирменные болты из оксидированной стали, классическая высокая посадка и эффект естественного фейдинга со временем.','100% хлопок Selvedge Denim (14.5 oz)','Первые 6 месяцев не стирать для формирования естественных заломов (fade). Затем деликатная стирка в холодной воде.','Курьерская доставка по всей России с возможностью оплаты после примерки.','./images/cargo_pants.jpg',array['./images/cargo_pants.jpg','https://dieyoung.store/item/raw-concrete-denim','Raw Indigo / Dark Gray','DY-24-DNM-08']::text[],null,false,false,null,null,'published'),
('yalta94-panama-utility','Панама с ремнем «Seaside Blackout»',(select id from public.brands where slug='yalta-94'),'accessories','Аксессуары',2900,array[]::text[],'Утилитарная панама из влагоотталкивающей мембранной ткани с широкими простроченными полями, регулировочным ремешком с фастексом и вентиляционными люверсами.','100% нейлон с водоотталкивающим тефлоновым слоем','Протирать влажной тканью.','Отправка почтой или СДЭК из Крыма.','./images/oversize_tee.jpg',array['./images/oversize_tee.jpg','https://yalta94.com/shop/panama-blackout','Jet Black','YLT-24-PNM-02']::text[],null,false,false,null,null,'published'),
('volchok-cyber-tee','Футболка Boxy «Черный Монолит»',(select id from public.brands where slug='volchok'),'t-shirts','Футболки',4800,array[]::text[],'Классический квадратный бокси-силуэт с плотной горловиной. Трафаретная печать пластизолевыми чернилами с эффектом кракелюра, глубокий черный оттенок ткани и минималистичная эстетика.','100% вычесанный хлопок (250 г/м²)','Стирка 30°C, гладить через ткань.','Доставка 1-3 дня в любой город РФ.','./images/oversize_tee.jpg',array['./images/oversize_tee.jpg','https://volchok.ru/catalog/tee-monolith','Deep Coal','VLC-24-TEE-11']::text[],null,false,false,null,null,'published'),
('hrdcr-crewneck-heavy','Свитшот Heavyweight «Nordic Resistance»',(select id from public.brands where slug='hrdcr'),'hoodies','Худи и свитшоты',7900,array[]::text[],'Массивный свитшот без капюшона с широкими трикотажными резинками на поясе и манжетах. Винтажный треугольник на вороте, плотная трехнитка 450 г/м², петербургский локальный пошив.','100% хлопковый футер диагональ','Деликатная машинная стирка 30°C.','СДЭК или самовывоз в Санкт-Петербурге.','./images/hoodie_black.jpg',array['./images/hoodie_black.jpg','https://hrdcr.ru/products/crewneck-resistance','Asphalt Gray','HRD-24-CRW-06']::text[],null,false,false,null,null,'published')
on conflict (slug) do update set
  name=excluded.name, brand_id=excluded.brand_id, category=excluded.category,
  category_label=excluded.category_label, price=excluded.price, sizes=excluded.sizes,
  description=excluded.description, composition=excluded.composition,
  care_instructions=excluded.care_instructions, delivery_info=excluded.delivery_info,
  image_url=excluded.image_url, gallery=excluded.gallery,
  external_shop_url=excluded.external_shop_url, is_new=excluded.is_new,
  featured=excluded.featured, color=excluded.color, sku=excluded.sku,
  status='published', updated_at=now();

commit;
